export function getPageData(slug: string, lang: string): PageTranslationData {
  const cleanLang = (lang || 'en').toLowerCase().split('-')[0];
  const langDict = PAGE_TRANSLATIONS[cleanLang] || PAGE_TRANSLATIONS['en'];
  const data = langDict[slug] || PAGE_TRANSLATIONS['en'][slug];

  if (!data) {
    const enFallback = PAGE_TRANSLATIONS['en']['age-calculator'];
    return {
      title: 'Age Calculator',
      description: 'Calculate your exact age in years, months, and days.',
      heroTitle: 'Age Calculator',
      heroSubtitle: 'Calculate your exact age with precision.',
      breadcrumb: 'Calculator',
      faqs: enFallback.faqs
    };
  }

  return data;
}
